package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct { // 01 DISC-REC, 15 bytes
	DrItem  string          // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct   int64           // PIC 9(2) @13 len=2
}

var WsEofFlag string = "N"
var WsDiscount decimal.Decimal = decimal.NewFromInt(0)
var WsNet decimal.Decimal = decimal.NewFromInt(0)
var WsTotalNet decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPriceEd string
var WsDiscEd string
var WsNetEd string
var WsTotalEd string

var discRec DiscRec
var discRecords []DiscRec
var discIdx int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func pow10Int64(n int) int64 {
	var r int64 = 1
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func parsePrice(s string) decimal.Decimal {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else if c == ' ' {
			d = 0
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return decimal.New(n, -2)
}

func parsePct(s string) int64 {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else if c == ' ' {
			d = 0
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return n
}

func parseDiscRec(line string) DiscRec {
	item := line[0:6]
	priceStr := line[6:13]
	pctStr := line[13:15]
	return DiscRec{
		DrItem:  item,
		DrPrice: parsePrice(priceStr),
		DrPct:   parsePct(pctStr),
	}
}

func fitToPic(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	shifted := v.Shift(int32(scale)).Truncate(0)
	cents := shifted.IntPart()
	mod := pow10Int64(intDigits + scale)
	wrapped := cents % mod
	return decimal.New(wrapped, int32(-scale))
}

func formatEdited(v decimal.Decimal, pic string) string {
	dotIdx := strings.Index(pic, ".")
	var intPic, decPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		decPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		decPic = ""
	}
	intSlots := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intSlots++
		}
	}
	decPlaces := 0
	for _, ch := range decPic {
		if ch == 'Z' || ch == '9' {
			decPlaces++
		}
	}
	totalDigits := intSlots + decPlaces
	absVal := v.Abs().Truncate(int32(decPlaces))
	shifted := absVal.Shift(int32(decPlaces)).Truncate(0).IntPart()
	mod := pow10Int64(totalDigits)
	var wrapped int64
	if mod != 0 {
		wrapped = shifted % mod
	} else {
		wrapped = shifted
	}
	var intPart, fracPart int64
	if decPlaces > 0 {
		div := pow10Int64(decPlaces)
		intPart = wrapped / div
		fracPart = wrapped % div
	} else {
		intPart = wrapped
		fracPart = 0
	}
	intDigits := make([]int, intSlots)
	tmp := intPart
	for i := intSlots - 1; i >= 0; i-- {
		intDigits[i] = int(tmp % 10)
		tmp /= 10
	}
	fracDigits := make([]int, decPlaces)
	tmpF := fracPart
	for i := decPlaces - 1; i >= 0; i-- {
		fracDigits[i] = int(tmpF % 10)
		tmpF /= 10
	}
	var sb strings.Builder
	slotIdx := 0
	suppressed := true
	for _, ch := range intPic {
		if ch == 'Z' {
			d := intDigits[slotIdx]
			slotIdx++
			if suppressed && d == 0 {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(byte('0' + d))
				suppressed = false
			}
		} else if ch == '9' {
			d := intDigits[slotIdx]
			slotIdx++
			sb.WriteByte(byte('0' + d))
			suppressed = false
		} else if ch == ',' {
			if suppressed {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(',')
			}
		} else {
			sb.WriteByte(byte(ch))
		}
	}
	if dotIdx >= 0 {
		sb.WriteByte('.')
		fIdx := 0
		for _, ch := range decPic {
			if ch == 'Z' || ch == '9' {
				sb.WriteByte(byte('0' + fracDigits[fIdx]))
				fIdx++
			} else {
				sb.WriteByte(byte(ch))
			}
		}
	}
	return sb.String()
}

func openDiscFile() {
	discRecords = nil
	discIdx = 0
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			discRecords = []DiscRec{}
			discIdx = 0
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		if len(line) < 15 {
			line = line + strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			line = line[:15]
		}
		rec := parseDiscRec(line)
		discRecords = append(discRecords, rec)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if discRecords == nil {
		discRecords = []DiscRec{}
	}
}

func closeDiscFile() {
}

func MainPara() {
	openDiscFile()
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	closeDiscFile()
	SummaryPara()
}

func ReadPara() {
	if discIdx >= len(discRecords) {
		WsEofFlag = "Y"
	} else {
		discRec = discRecords[discIdx]
		discIdx++
	}
}

func ProcessPara() {
	tmp := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct)).Shift(-2)
	rounded := tmp.Round(2)
	WsDiscount = fitToPic(rounded, 5, 2)
	tmp2 := discRec.DrPrice.Sub(WsDiscount)
	trunc := tmp2.Truncate(2)
	WsNet = fitToPic(trunc, 5, 2)
	sum := WsTotalNet.Add(WsNet).Truncate(2)
	WsTotalNet = fitToPic(sum, 8, 2)
	WsCount = (WsCount + 1) % 1000
	WsPriceEd = formatEdited(discRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")
	pctMod := ((discRec.DrPct % 100) + 100) % 100
	pctStr := fmt.Sprintf("%02d", pctMod)
	line := discRec.DrItem + " " + WsPriceEd + " " + pctStr + "% " + WsDiscEd + " " + WsNetEd
	fmt.Fprint(os.Stdout, line+"\n")
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	cntMod := ((WsCount % 1000) + 1000) % 1000
	countStr := fmt.Sprintf("%03d", cntMod)
	line := "ITEMS: " + countStr + " NET TOTAL: " + WsTotalEd
	fmt.Fprint(os.Stdout, line+"\n")
}

func main() {
	MainPara()
}
